window.docContents[245].resolve({"/6___-Quiver-representations/6___5___-Gabriel___s-theorem/Theorem-6___5___2___-Gabriel___s-theorem/#Chapter6___Theorem6___5___2":{"contents":"Theorem 6.5.2 (Gabriel's theorem). Let Q be a quiver of type A_n, D_n, E_6, E_7, E_8. Then Q has finitely many indecomposable representations. Namely, the dimension vector of any indecomposable representation is a positive root (with respect to B_\\Gamma) and for any positive root \\alpha there is exactly one indecomposable representation with dimension vector \\alpha.\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.5. Gabriel's theorem\tTheorem 6.5.2: Gabriel's theorem","header":"Theorem 6.5.2: Gabriel's theorem","id":"/6___-Quiver-representations/6___5___-Gabriel___s-theorem/Theorem-6___5___2___-Gabriel___s-theorem/#Chapter6___Theorem6___5___2"},"/7___-Introduction-to-categories/7___9___-Exact-functors/Section-7___9___-Exact-functors/#Chapter7___Introduction_7___9___heading-1":{"contents":"","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.9. Exact functors\tSection 7.9: Exact functors","header":"7.9. Exact functors","id":"/7___-Introduction-to-categories/7___9___-Exact-functors/Section-7___9___-Exact-functors/#Chapter7___Introduction_7___9___heading-1"}});
